1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = { itemType: string; amount: number };
14	
15	export type ClaimStep = {
16	  op: "claim";
17	  policy: number;
18	  incident: { cause: string; damages: Damage[] };
19	};
20	
21	export type Step = QuoteStep | ClaimStep;
22	
23	export type Customer = { yearsWithMHPCO: number };
24	
25	export type Scenario = {
26	  customer: Customer;
27	  steps: Step[];
28	};
29	
30	export type ScenarioResults = {
31	  results: unknown[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
36	const LOYALTY_DISCOUNT = 0.2;
37	const LOYALTY_YEARS = 2;
38	const FOLLOW_UP_DISCOUNT = 0.15;
39	
40	const BASE_PREMIUMS: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	
49	const INSURANCE_VALUES: Record<string, number> = {
50	  sword: 1000,
51	  amulet: 600,
52	  staff: 800,
53	  potion: 400,
54	  rune: 250,
55	  moonstone: 250,
56	};
57	
58	const DEDUCTIBLE = 100;
59	const CAP_MULTIPLE = 2;
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	
66	/** Items are priced per type, because the component block applies to alike items. */
67	const groupByType = (items: Item[]): Map<string, Item[]> =>
68	  items.reduce(
69	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
70	    new Map<string, Item[]>(),
71	  );
72	
73	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
74	
75	/**
76	 * Item-level risk surcharges, each a rate on the item's own base premium.
77	 * They are separate addends: unlike the policy-level initial assessment, they
78	 * do not compound with each other or with it.
79	 */
80	const CURSE_SURCHARGE = 0.5;
81	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
82	const HIGH_ENCHANTMENT_LEVEL = 5;
83	
84	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
85	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
86	  {
87	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
88	    rate: HIGH_ENCHANTMENT_SURCHARGE,
89	  },
90	];
91	
92	const itemSurchargeTotal = (item: Item): number =>
93	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
94	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
95	    0,
96	  );
97	
98	/**
99	 * A building block of exactly 3 alike components is offered at a special base
100	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
101	 * runes are charged per item.
102	 */
103	const formsComponentBlock = (type: string, items: Item[]): boolean =>
104	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
105	
106	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
107	  formsComponentBlock(type, items)
108	    ? BLOCK_BASE_PREMIUM
109	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
110	
111	const policyBasePremium = (items: Item[]): number =>
112	  [...groupByType(items)].reduce(
113	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
114	    0,
115	  );
116	
117	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
118	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
119	
120	/**
121	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
122	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
123	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
124	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
125	 */
126	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
127	
128	const policyItemSurchargeTotal = (items: Item[]): number =>
129	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
130	
131	/**
132	 * Policy-level modifiers, each a signed rate on the policy base premium.
133	 * Like the item-level surcharges they are independent addends: they do not
134	 * compound with one another. A discount is simply a negative rate.
135	 */
136	type Policy = { items: Item[] };
137	
138	type ScenarioState = {
139	  customer: Customer;
140	  contractsIssued: number;
141	  policies: Map<number, Policy>;
142	};
143	
144	const POLICY_MODIFIER_RULES: { applies: (state: ScenarioState) => boolean; rate: number }[] = [
145	  {
146	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
147	    rate: -LOYALTY_DISCOUNT,
148	  },
149	  { applies: ({ contractsIssued }) => contractsIssued > 0, rate: -FOLLOW_UP_DISCOUNT },
150	];
151	
152	const policyModifierTotal = (basePremium: number, state: ScenarioState): number =>
153	  POLICY_MODIFIER_RULES.filter(({ applies }) => applies(state)).reduce(
154	    (sum, { rate }) => sum + basePremium * rate,
155	    0,
156	  );
157	
158	/**
159	 * The premium is the policy base premium plus a set of independent addends,
160	 * each a rate on that same base — they do not compound with one another:
161	 *
162	 *   100 base + 50 curse + 30 high ench - 20 loyalty + 10 first insurance = 170, + 5 fee
163	 *
164	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
165	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
166	 * documented there.
167	 */
168	const quote = (step: QuoteStep, state: ScenarioState): { premium: number } => {
169	  const basePremium = policyBasePremium(step.items);
170	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
171	  const itemSurcharges = policyItemSurchargeTotal(step.items);
172	  const policyModifiers = policyModifierTotal(basePremium, state);
173	
174	  return {
175	    premium: roundInMHPCOsFavour(
176	      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
177	    ),
178	  };
179	};
180	
181	/** Payouts are rounded in the MHPCO's favour, i.e. down. */
182	const roundPayoutInMHPCOsFavour = (payout: number): number => Math.floor(payout);
183	
184	const insuranceSum = (items: Item[]): number =>
185	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
186	
187	/** A deductible applies per damage event, i.e. once per damaged item. */
188	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;
189	
190	const claim = (
191	  step: ClaimStep,
192	  state: ScenarioState,
193	): { payout: number; remainingCap: number } => {
194	  const policy = state.policies.get(step.policy) as Policy;
195	  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
196	  const payout = roundPayoutInMHPCOsFavour(
197	    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0),
198	  );
199	
200	  return { payout, remainingCap: cap - payout };
201	};
202	
203	/**
204	 * Steps are processed in order and later steps depend on earlier ones — a quote
205	 * issues a contract that discounts every following quote, and a claim is made
206	 * against a policy an earlier quote created. Each step therefore maps its
207	 * incoming state to a result plus the state the next step sees.
208	 */
209	const runStep = (
210	  step: Step,
211	  state: ScenarioState,
212	  index: number,
213	): { result: unknown; nextState: ScenarioState } =>
214	  step.op === "quote"
215	    ? {
216	        result: quote(step, state),
217	        nextState: {
218	          ...state,
219	          contractsIssued: state.contractsIssued + 1,
220	          policies: new Map(state.policies).set(index, { items: step.items }),
221	        },
222	      }
223	    : { result: claim(step, state), nextState: state };
224	
225	export const runScenario = (scenario: Scenario): ScenarioResults => {
226	  const { results } = scenario.steps.reduce<{
227	    results: unknown[];
228	    state: ScenarioState;
229	  }>(
230	    ({ results, state }, step, index) => {
231	      const { result, nextState } = runStep(step, state, index);
232	
233	      return { results: [...results, result], state: nextState };
234	    },
235	    {
236	      results: [],
237	      state: { customer: scenario.customer, contractsIssued: 0, policies: new Map() },
238	    },
239	  );
240	
241	  return { results };
242	};
